diff --git a/src/media_tools/crypt_tools.c b/src/media_tools/crypt_tools.c
index cf22245..d0042fe 100644
--- a/src/media_tools/crypt_tools.c
+++ b/src/media_tools/crypt_tools.c
@@ -177,6 +177,13 @@ static GF_Err crypt_cpix_decode_b64(const char *input, u8 **out_data, u32 *out_s
 	return GF_OK;
 }

+static GF_Err crypt_cpix_decode_xml_text(char *text, u8 **out_data, u32 *out_size)
+{
+	GF_Err e = crypt_cpix_decode_b64(text, out_data, out_size);
+	if (text) gf_free(text);
+	return e;
+}
+
 static u32 crypt_cpix_read_u32(const u8 *data)
 {
 	return ((u32)data[0] << 24) | ((u32)data[1] << 16) | ((u32)data[2] << 8) | data[3];
@@ -448,11 +455,17 @@ static GF_Err cryptinfo_load_cpix(const char *file, GF_CryptInfo **out_info)
 		goto exit;
 	}

+	GF_XMLNode *plain_text_node = plain_node->content ? (GF_XMLNode *) gf_list_get(plain_node->content, 0) : NULL;
 	text = crypt_xml_get_text(plain_node);
-	e = crypt_cpix_decode_b64(text, &decoded, &decoded_size);
-	if (text) {
-		gf_free(text);
+	if (plain_text_node && (plain_text_node->type == GF_XML_CDATA_TYPE)) {
+		e = crypt_cpix_decode_xml_text(text, &decoded, &decoded_size);
 		text = NULL;
+	} else {
+		e = crypt_cpix_decode_b64(text, &decoded, &decoded_size);
+		if (text) {
+			gf_free(text);
+			text = NULL;
+		}
 	}
 	if (e || (decoded_size != 16)) {
 		GF_LOG(GF_LOG_ERROR, GF_LOG_PARSER, ("[CPIX] ContentKey PlainValue must decode to 16 bytes\n"));

